    def maxAreaOfIsland(self, grid: List[List[int]]) -> int:
        rows, cols = len(grid), len(grid[0])

        def flood(r: int, c: int) -> int:
            grid[r][c] = 0
            stack, area = [(r, c)], 1
            while stack:
                x, y = stack.pop()
                for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                    if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == 1:
                        grid[nx][ny] = 0  # claim on push so each cell is counted once
                        area += 1
                        stack.append((nx, ny))
            return area

        best = 0
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 1:
                    best = max(best, flood(r, c))
        return best

class Solution:
    def pacificAtlantic(self, heights: List[List[int]]) -> List[List[int]]:
        rows, cols = len(heights), len(heights[0])

        def climb(sources: List[tuple]) -> List[List[bool]]:
            seen = [[False] * cols for _ in range(rows)]
            queue = deque(sources)
            for r, c in sources:
                seen[r][c] = True
            while queue:
                r, c = queue.popleft()
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if 0 <= nr < rows and 0 <= nc < cols and not seen[nr][nc] \
                            and heights[nr][nc] >= heights[r][c]:  # reverse flow: go uphill
                        seen[nr][nc] = True
                        queue.append((nr, nc))
            return seen

        pacific = [(r, 0) for r in range(rows)] + [(0, c) for c in range(cols)]
        atlantic = [(r, cols - 1) for r in range(rows)] + [(rows - 1, c) for c in range(cols)]
        pac, atl = climb(pacific), climb(atlantic)
        return [[r, c] for r in range(rows) for c in range(cols) if pac[r][c] and atl[r][c]]

