        adj = [[] for _ in range(numCourses)]
        indeg = [0] * numCourses
        for course, pre in prerequisites:
            adj[pre].append(course)
            indeg[course] += 1
        queue = deque(c for c in range(numCourses) if indeg[c] == 0)
