    # DFS from every node with a private visited set; count the node only if it is the
    # smallest id in the component it reaches.
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    count = 0
    for start in range(n):
        seen, stack = {start}, [start]
        while stack:
            cur = stack.pop()
            for nb in adj[cur]:
                if nb not in seen:
                    seen.add(nb)
                    stack.append(nb)
        if min(seen) == start:
            count += 1
    return count

