def brute_force(times: List[List[int]], n: int, k: int) -> int:
    # Bellman-Ford: n-1 rounds, each relaxing EVERY edge.
    INF = float("inf")
    dist = [INF] * (n + 1)
    dist[k] = 0
    for _ in range(n - 1):
        for u, v, w in times:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
    worst = max(dist[1:])
    return -1 if worst == INF else worst

