def brute_force(intervals: List[List[int]], newInterval: List[int]) -> List[List[int]]:
    # Ignore the sorted/disjoint guarantee: add the interval, sort, and merge generically.
    ivs = sorted([iv[:] for iv in intervals] + [newInterval[:]])
    merged = [ivs[0]]
    for s, e in ivs[1:]:
        if s <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], e)
        else:
            merged.append([s, e])
    return merged

def brute_force(intervals: List[List[int]]) -> int:
    # Enumerate every subset; keep the largest that is pairwise non-overlapping.
    n = len(intervals)
    best = 0
    for mask in range(1 << n):
        chosen = [intervals[i] for i in range(n) if mask >> i & 1]
        ok = all(a[1] <= b[0] or b[1] <= a[0]
                 for i, a in enumerate(chosen) for b in chosen[i + 1:])
        if ok:
            best = max(best, len(chosen))
    return n - best

