class Solution:
    def eraseOverlapIntervals(self, intervals: List[List[int]]) -> int:
        intervals.sort(key=lambda iv: iv[1])  # earliest end first
        removed, last_end = 0, float("-inf")
        for start, end in intervals:
            if start >= last_end:
                last_end = end  # keep: it starts after the last kept one finishes
            else:
                removed += 1  # overlaps the kept one, which ends no later: drop this
        return removed

class Solution:
    def minMeetingRooms(self, intervals: List[List[int]]) -> int:
        intervals.sort(key=lambda iv: iv[0])
        ends = []  # min-heap of end times of meetings currently occupying a room
        rooms = 0
        for start, end in intervals:
            while ends and ends[0] <= start:
                heapq.heappop(ends)  # that room is free again
            heapq.heappush(ends, end)
            rooms = max(rooms, len(ends))
        return rooms
